python3 - <<'EOF'
import os
for root, dirs, files in os.walk('.'):
    # skip hidden dirs like .git, node_modules
    dirs[:] = [d for d in dirs if not d.startswith('.') or d == '.codex']
    for f in files:
        if f.endswith('.pdf'):
            print(os.path.join(root, f))
